import numpy as np
import matplotlib.pyplot as plt

def plot_curve_over_time(curve):
    """
    Plots X over time and Y over time for a given curve.

    Parameters:
    curve (array-like): A sequence of (x, y, vx, vy, ms) points.

    Returns:
    None
    """
    curve = np.array(curve)
    time_values = curve[:, 4]  # Extract the ms (actual time) values
    
    x_values = curve[:, 0]
    y_values = curve[:, 1]
    
    plt.figure(figsize=(10, 5))
    
    # Plot X over actual time
    plt.subplot(1, 2, 1)
    plt.plot(time_values, x_values, marker='o', linestyle='-', label='X over time')
    plt.xlabel('Time (ms)')
    plt.ylabel('X Value')
    plt.title('X Over Time')
    plt.legend()
    
    # Plot Y over actual time
    plt.subplot(1, 2, 2)
    plt.plot(time_values, y_values, marker='o', linestyle='-', label='Y over time', color='r')
    plt.xlabel('Time (ms)')
    plt.ylabel('Y Value')
    plt.title('Y Over Time')
    plt.legend()
    
    plt.tight_layout()


def estimate_gravity(t, y):
    """
    Estimates the in-game gravity based on the trajectory of a falling object.

    Parameters:
    t (array-like): Time values (in milliseconds).
    y (array-like): Vertical position values.

    Returns:
    float: Estimated gravity value.
    """
    # Fit a quadratic curve: y = a*t^2 + v0*t + y0
    coeffs = np.polyfit(t, y, 2)  # Returns [a, v0, y0]

    # Extract gravity (acceleration)
    a = 2 * coeffs[0]  # Since the equation gives (1/2) * a * t^2

    return a


def extract_initial_values(curve, num_points=5):
    """Extracts initial position (x0, y0) and velocity (vx0, vy0) using the first `num_points` time steps."""
    t = curve[:, 4]  # Time values (ms)
    x = curve[:, 0]  # X values
    y = curve[:, 1]  # Y values
    
    x0 = x[0]   # Initial X position
    y0 = y[0]   # Initial Y position
    t0 = t[0]   # Initial time
    
    # Ensure there are enough points to calculate velocity
    if len(t) < num_points:
        return -1
    
    # Use the first `num_points` points for better velocity approximation
    delta_x = x[num_points-1] - x[0]  # Change in X position
    delta_t = t[num_points-1] - t[0]  # Change in time
    vx0 = delta_x / delta_t  # Initial velocity in X direction
    
    # Fit a quadratic model y = a*t^2 + b*t + c to estimate vy0
    t_subset = t[:num_points] - t0  # Shift time so that t0 = 0
    y_subset = y[:num_points]
    
    coeffs = np.polyfit(t_subset, y_subset, 2)  # Fit quadratic curve
    a, b, c = coeffs  # a is acceleration component, b is initial velocity, c is initial position
    
    g = a   # Estimated gravity 
    vy0 = b # Initial velocity in Y direction
    
    return x0, y0, vx0, vy0, t0, g


def plot_curve_over_time(curve, pred_curve):
    """
    Plots X over time and Y over time for a given curve, comparing actual and predicted values.

    Parameters:
    curve (array-like): A sequence of (x, y, vx, vy, ms) points (actual values).
    pred_curve (array-like): A sequence of predicted (x, y) values.

    Returns:
    None
    """
    curve = np.array(curve)
    pred_curve = np.array(pred_curve)

    time_values = curve[:, 4]  # Extract the ms (actual time) values
    x_values = curve[:, 0]     # Actual X values
    y_values = curve[:, 1]     # Actual Y values
    
    # Predicted values
    x_pred = pred_curve[:, 0]  # Predicted X values
    y_pred = pred_curve[:, 1]  # Predicted Y values
    
    plt.figure(figsize=(10, 5))

    # Plot X over actual time
    plt.subplot(1, 2, 1)
    plt.plot(time_values, x_values, marker='o', linestyle='-', label='Actual X')
    plt.plot(time_values, x_pred, marker='x', linestyle='--', label='Predicted X')
    plt.xlabel('Time (ms)')
    plt.ylabel('X Value')
    plt.title('X Over Time')
    plt.legend()

    # Plot Y over actual time
    plt.subplot(1, 2, 2)
    plt.plot(time_values, y_values, marker='o', linestyle='-', label='Actual Y', color='r')
    plt.plot(time_values, y_pred, marker='x', linestyle='--', label='Predicted Y', color='b')
    plt.xlabel('Time (ms)')
    plt.ylabel('Y Value')
    plt.title('Y Over Time')
    plt.legend()

    plt.tight_layout()


