    x_actual = curve[:, 0]
    y_actual = curve[:, 1]

    # Extract initial conditions for prediction (now includes vx0 and vy0)
    x0, y0, vx0, vy0, t0, g = extract_initial_values(curve, num_points=20)
    
    # Predict y using kinematic equation (y = y0 + vy0 * t + * g * t^2)
