    y_pred = y0 + vy0 * (t-t0) + g * (t-t0)**2  # Predicted Y values based on gravity
    
    # Predict x using constant velocity equation (x = x0 + vx0 * t)
    x_pred = x0 + vx0 * (t-t0)  # Constant velocity model for X

    # Prepare predicted curve
    pred_curve = np.column_stack((x_pred, y_pred))  # Combine predicted x and y values

    # Plot actual and predicted curves
    plot_curve_over_time(curve, pred_curve)
    plt.show()